import { TableLoadMoreItem } from '@/components/ui/table-load-more';

export function TableLoadMoreDemo() {
  const [rows, setRows] = useState([1, 2, 3]);
  return (
    <table>
      <caption>Local practice notes</caption>
      <thead>
        <tr>
          <th scope="col">Note</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((id) => (
          <tr key={id}>
            <td>Plan {id}</td>
          </tr>
        ))}
        <TableLoadMoreItem
          loadKey={rows.length}
          hasMore={rows.length < 9}
          onLoadMore={async ({ signal }) => {
            // Local demo data; replace this with your own data source.
            if (signal.aborted) return;
            setRows((current) => [
              ...current,
              current.length + 1,
              current.length + 2,
              current.length + 3,
            ]);
          }}
        />
      </tbody>
    </table>
  );
}

sonner:
'use client';

import { useId, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Sonner, sonner } from '@/components/ui/sonner';

export function SonnerDemo() {
  const toasterId = useId();
  const [outcome, setOutcome] = useState('');
  return (
    <>
      <Sonner id={toasterId} closeButton />
      <div className="flex flex-wrap justify-center gap-3">
        <Button onClick={() => sonner('Default Sonner', { toasterId })}>
          Show notification
        </Button>
        <Button
          onClick={() =>
            sonner.success('Sonner with Success Icon', {
              toasterId,
              description: 'This notification includes an icon.',
            })
          }
        >
          Success
        </Button>
        <Button
          onClick={() =>
            sonner('Sonner with Action', {
              toasterId,
              description: 'This notification includes an action.',
              action: {
                label: 'Undo',
                onClick: () => setOutcome('Changes undone'),
              },
            })
          }
        >
          With action
        </Button>
        <Button
          onClick={() =>
            sonner.promise(
              new Promise<string>((resolve) =>
                setTimeout(() => resolve('Build saved'), 1500),
              ),
              {
                toasterId,
                loading: 'Saving build…',
                success: (value) => value,
                error: 'Unable to save',
              },
            )
          }
        >
          Promise
        </Button>
      </div>
      {outcome && <p role="status">{outcome}</p>}
    </>
  );
}

